            modelBuilder
                .Entity<CarModelEntity>()
                .ToTable("Models", schema: SchemaNames.Cars);

            modelBuilder.Entity<CarModelEntity>()
                .HasOne(m => m.CarBrand)
                .WithMany()
                .HasForeignKey(m => m.CarBrandId)
                .OnDelete(DeleteBehavior.Cascade);

            modelBuilder
                .Entity<CarModelEntity>()
                .HasData(
