        public static ModelBuilder AddCarOffers(this ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<CarOfferEntity>()
                .ToTable("CarOffers", schema: SchemaNames.Cars);

            modelBuilder
            .Entity<CarOfferEntity>()
            .HasOne(p => p.Coupe)
            .WithMany()
            .HasForeignKey(p => p.CoupeId)
            .OnDelete(DeleteBehavior.NoAction);

            modelBuilder
                .Entity<CarOfferEntity>()
                .HasOne(p => p.Brand)
                .WithMany()
                .HasForeignKey(p => p.BrandId)
                .OnDelete(DeleteBehavior.NoAction);

            modelBuilder
               .Entity<CarOfferEntity>()
               .HasOne(p => p.Model)
               .WithMany()
               .HasForeignKey(p => p.ModelId)
               .OnDelete(DeleteBehavior.NoAction);

            modelBuilder
               .Entity<CarOfferEntity>()
               .HasOne(p => p.Engine)
               .WithMany()
               .HasForeignKey(p => p.EngineId)
               .OnDelete(DeleteBehavior.NoAction);

            modelBuilder
               .Entity<CarOfferEntity>()
               .HasOne(p => p.Transmission)
               .WithMany()
               .HasForeignKey(p => p.TransmissionId)
               .OnDelete(DeleteBehavior.NoAction);

            modelBuilder
               .Entity<CarOfferEntity>()
               .HasOne(p => p.Material)
               .WithMany()
               .HasForeignKey(p => p.MaterialId)
               .OnDelete(DeleteBehavior.NoAction);

            modelBuilder
               .Entity<CarOfferEntity>()
               .HasOne(p => p.Region)
               .WithMany()
               .HasForeignKey(p => p.RegionId)
               .OnDelete(DeleteBehavior.NoAction);

            modelBuilder
               .Entity<CarOfferEntity>()
               .HasOne(p => p.Location)
               .WithMany()
               .HasForeignKey(p => p.LocationId)
               .OnDelete(DeleteBehavior.NoAction);

            modelBuilder
               .Entity<CarOfferEntity>()
               .HasOne(p => p.EuroStandard)
               .WithMany()
               .HasForeignKey(p => p.EuroStandardId)
               .OnDelete(DeleteBehavior.NoAction);

            modelBuilder
               .Entity<CarOfferEntity>()
               .HasOne(p => p.Currency)
               .WithMany()
               .HasForeignKey(p => p.CurrencyId)
               .OnDelete(DeleteBehavior.NoAction);

            return modelBuilder;
        }

        public static ModelBuilder AddOfferImages(this ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<OfferImageEntity>()
                .ToTable("OfferImages", schema: SchemaNames.Troshka);

            modelBuilder.Entity<CarOfferEntity>()
                .HasMany(c => c.Images)
                .WithOne(o => o.CarOffer)
                .HasForeignKey(o => o.OfferId);

            return modelBuilder;
        }

        public static ModelBuilder AddUsers(this ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<UserEntity>()
                .ToTable("Users", schema: SchemaNames.Troshka);

            modelBuilder.Entity<UserEntity>()
                .HasMany(c => c.Comments)
                .WithOne(o => o.Author)
                .HasForeignKey(o => o.AuthorId)
                .OnDelete(DeleteBehavior.Restrict);

            return modelBuilder;
        }

        public static ModelBuilder AddUserComments(this ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<UserCommentsEntity>()
                .ToTable("UserComments", schema: SchemaNames.Troshka);

            modelBuilder.Entity<UserCommentsEntity>()
                .HasOne(p => p.Author);

            modelBuilder.Entity<UserCommentsEntity>()
                .HasOne(p => p.Recipient);

            return modelBuilder;
        }

